<template>
  <q-page class="idea-board q-pa-md">
    <!-- Header -->
    <div class="row items-center justify-between q-mb-md">
      <div class="text-h5 text-weight-bold">{{ $t('idea_board') }}</div>
      <q-btn
        color="primary"
        icon="add"
        :label="$t('new_idea')"
        no-caps
        @click="showNewIdeaDialog = true"
      />
    </div>

    <!-- Filters -->
    <div class="row q-gutter-sm q-mb-md items-center">
      <q-select
        v-model="selectedCategory"
        :options="categoryOptions"
        :option-label="(opt: { label: string }) => $t(opt.label)"
        :label="$t('idea_category')"
        emit-value
        map-options
        clearable
        dense
        outlined
        style="min-width: 150px"
        @update:model-value="onFilterChange"
      />
      <q-select
        v-model="selectedStatus"
        :options="statusOptions"
        :option-label="(opt: { label: string }) => $t(opt.label)"
        :label="$t('idea_status')"
        emit-value
        map-options
        clearable
        dense
        outlined
        style="min-width: 150px"
        @update:model-value="onFilterChange"
      />
      <q-input
        v-model="searchText"
        :placeholder="$t('search') + '...'"
        dense
        outlined
        clearable
        debounce="400"
        style="min-width: 200px"
        @update:model-value="onFilterChange"
      >
        <template #prepend>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-select
        v-model="selectedSort"
        :options="sortOptions"
        :option-label="(opt: { label: string }) => $t(opt.label)"
        emit-value
        map-options
        dense
        outlined
        style="min-width: 140px"
        @update:model-value="onFilterChange"
      />
    </div>

    <!-- Loading -->
    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner size="48px" color="primary" />
    </div>

    <!-- Empty state -->
    <div
      v-else-if="ideas.length === 0"
      class="text-center q-pa-xl text-grey-6"
    >
      <q-icon name="lightbulb" size="64px" class="q-mb-md" />
      <div class="text-h6">{{ $t('no_ideas_yet') }}</div>
      <div class="text-body2 q-mt-sm">{{ $t('be_first_to_share') }}</div>
    </div>

    <!-- Ideas list -->
    <div v-else class="q-gutter-md">
      <q-card
        v-for="idea in ideas"
        :key="idea.id"
        flat
        bordered
        class="idea-card"
      >
        <q-card-section class="row no-wrap items-start q-gutter-md">
          <!-- Vote button -->
          <div class="vote-section text-center">
            <q-btn
              flat
              round
              :icon="hasVoted(idea.id) ? 'thumb_up' : 'thumb_up_off_alt'"
              :color="hasVoted(idea.id) ? 'primary' : 'grey-6'"
              @click="onVote(idea.id)"
            />
            <div
              class="text-weight-bold"
              :class="hasVoted(idea.id) ? 'text-primary' : 'text-grey-7'"
            >
              {{ idea.vote_count }}
            </div>
          </div>

          <!-- Content -->
          <div class="col">
            <div class="row items-center q-gutter-sm q-mb-xs">
              <q-badge
                :color="categoryColor(idea.category)"
                :label="$t('idea_category_' + idea.category)"
                class="text-capitalize"
              />
              <q-chip
                :color="statusColor(idea.status)"
                text-color="white"
                size="sm"
                dense
                :label="$t('idea_status_' + idea.status)"
              />
              <q-space />
              <q-btn
                v-if="isCreator(idea)"
                flat
                round
                dense
                size="sm"
                icon="edit"
                color="grey-6"
                @click="onEditIdea(idea)"
              >
                <q-tooltip>{{ $t('edit') }}</q-tooltip>
              </q-btn>
              <q-btn
                v-if="isCreator(idea)"
                flat
                round
                dense
                size="sm"
                icon="delete"
                color="negative"
                @click="onDeleteIdea(idea)"
              >
                <q-tooltip>{{ $t('delete') }}</q-tooltip>
              </q-btn>
            </div>
            <div class="text-subtitle1 text-weight-medium q-mb-xs">
              {{ idea.title }}
            </div>
            <div
              v-if="idea.description"
              class="text-body2 text-grey-7 q-mb-sm idea-description"
              v-html="idea.description"
            />
            <div class="text-caption text-grey-5 row items-center q-gutter-sm">
              <span v-if="idea.creator_name">
                {{ idea.creator_name }}
                <span v-if="idea.creator_org_name">
                  ({{ idea.creator_org_name }})
                </span>
              </span>
              <span v-if="idea.created_on">
                &middot; {{ timeAgo(idea.created_on) }}
              </span>
            </div>
            <div class="row items-center q-mt-sm">
              <q-btn
                flat
                dense
                no-caps
                size="sm"
                icon="chat_bubble_outline"
                :label="$t('idea_comments') + (getCommentCount(idea.id) > 0 ? ' (' + getCommentCount(idea.id) + ')' : '')"
                color="primary"
                @click="onToggleComments(idea.id)"
              />
            </div>

            <!-- Comments Section -->
            <div v-if="expandedComments[idea.id]" class="q-mt-sm">
              <q-separator class="q-my-xs" />
              <div class="text-caption text-weight-medium q-mb-xs">{{ $t('idea_comments') }}</div>
              <div v-if="commentsLoading[idea.id]" class="text-center q-pa-sm">
                <q-spinner size="24px" color="primary" />
              </div>
              <template v-else>
                <div
                  v-for="comment in (ideasStore.comments[idea.id] || [])"
                  :key="comment.id"
                  class="q-mb-xs q-pa-xs"
                  style="border-left: 2px solid #e0e0e0; padding-left: 8px;"
                >
                  <div class="row items-center q-gutter-xs">
                    <span class="text-caption text-weight-medium">{{ comment.creator_name }}</span>
                    <span v-if="comment.created_on" class="text-caption text-grey-5">
                      &middot; {{ timeAgo(comment.created_on) }}
                    </span>
                    <q-space />
                    <q-btn
                      v-if="comment.user_id === currentUserId"
                      flat
                      round
                      dense
                      size="xs"
                      icon="close"
                      color="grey-5"
                      @click="onDeleteComment(idea.id, comment.id)"
                    />
                  </div>
                  <div class="text-body2">{{ comment.content }}</div>
                </div>
                <div class="row q-gutter-xs q-mt-xs">
                  <q-input
                    v-model="commentText[idea.id]"
                    dense
                    outlined
                    :placeholder="$t('add_comment') + '...'"
                    class="col"
                    @keyup.enter="onAddComment(idea.id)"
                  />
                  <q-btn
                    flat
                    dense
                    icon="send"
                    color="primary"
                    :disable="!commentText[idea.id]"
                    @click="onAddComment(idea.id)"
                  />
                </div>
              </template>
            </div>
          </div>
        </q-card-section>
      </q-card>
    </div>

    <!-- Pagination -->
    <div
      v-if="pagination.total_pages > 1"
      class="row justify-center q-mt-lg"
    >
      <q-pagination
        v-model="currentPage"
        :max="pagination.total_pages"
        :max-pages="7"
        direction-links
        boundary-links
        @update:model-value="onPageChange"
      />
    </div>

    <!-- New Idea Dialog -->
    <q-dialog v-model="showNewIdeaDialog">
      <q-card style="min-width: 450px; max-width: 600px">
        <q-card-section>
          <div class="text-h6">{{ $t('new_idea') }}</div>
        </q-card-section>

        <q-card-section class="q-gutter-md">
          <q-input
            v-model="newIdea.title"
            :label="$t('idea_title')"
            outlined
            :rules="[(val: string) => !!val || $t('field_required')]"
          />
          <div>
            <div class="text-caption text-grey-7 q-mb-xs">{{ $t('idea_description') }}</div>
            <q-editor
              v-model="newIdea.description"
              :toolbar="editorToolbar"
              min-height="120px"
              flat
              bordered
              content-class="idea-editor-content"
            />
            <input
              ref="fileInput"
              type="file"
              accept="image/*"
              style="display: none"
              @change="onFileSelected"
            />
            <q-btn
              flat
              dense
              no-caps
              icon="add_photo_alternate"
              :label="$t('add_image')"
              :loading="uploadingImage"
              color="grey-7"
              class="q-mt-xs"
              @click="fileInput?.click()"
            />
          </div>
          <q-select
            v-model="newIdea.category"
            :options="categoryOptions"
            :option-label="(opt: { label: string }) => $t(opt.label)"
            :label="$t('idea_category')"
            emit-value
            map-options
            outlined
          />
        </q-card-section>

        <q-card-actions align="right">
          <q-btn
            flat
            :label="$t('cancel')"
            @click="showNewIdeaDialog = false"
          />
          <q-btn
            color="primary"
            :label="$t('submit')"
            no-caps
            :disable="!newIdea.title"
            :loading="submitting"
            @click="onSubmitIdea"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
    <!-- Edit Idea Dialog -->
    <q-dialog v-model="showEditIdeaDialog">
      <q-card style="min-width: 450px; max-width: 600px">
        <q-card-section>
          <div class="text-h6">{{ $t('edit_idea') }}</div>
        </q-card-section>

        <q-card-section class="q-gutter-md">
          <q-input
            v-model="editIdea.title"
            :label="$t('idea_title')"
            outlined
            :rules="[(val: string) => !!val || $t('field_required')]"
          />
          <div>
            <div class="text-caption text-grey-7 q-mb-xs">{{ $t('idea_description') }}</div>
            <q-editor
              v-model="editIdea.description"
              :toolbar="editorToolbar"
              min-height="120px"
              flat
              bordered
              content-class="idea-editor-content"
            />
            <input
              ref="editFileInput"
              type="file"
              accept="image/*"
              style="display: none"
              @change="onEditFileSelected"
            />
            <q-btn
              flat
              dense
              no-caps
              icon="add_photo_alternate"
              :label="$t('add_image')"
              :loading="uploadingImage"
              color="grey-7"
              class="q-mt-xs"
              @click="editFileInput?.click()"
            />
          </div>
          <q-select
            v-model="editIdea.category"
            :options="categoryOptions"
            :option-label="(opt: { label: string }) => $t(opt.label)"
            :label="$t('idea_category')"
            emit-value
            map-options
            outlined
          />
        </q-card-section>

        <q-card-actions align="right">
          <q-btn
            flat
            :label="$t('cancel')"
            @click="showEditIdeaDialog = false"
          />
          <q-btn
            color="primary"
            :label="$t('save')"
            no-caps
            :disable="!editIdea.title"
            :loading="submittingEdit"
            @click="onSubmitEdit"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Delete Confirmation Dialog -->
    <q-dialog v-model="showDeleteDialog">
      <q-card>
        <q-card-section>
          <div class="text-h6">{{ $t('confirm_delete') }}</div>
          <div class="q-mt-sm">{{ $t('delete_idea_confirm') }}</div>
        </q-card-section>
        <q-card-actions align="right">
          <q-btn flat :label="$t('cancel')" @click="showDeleteDialog = false" />
          <q-btn
            color="negative"
            :label="$t('delete')"
            @click="onConfirmDelete"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </q-page>
</template>

<script lang="ts">
import { defineComponent, ref, reactive, onMounted } from 'vue';
import { storeToRefs } from 'pinia';
import { useIdeasStore } from 'src/store/main';
import { useUserStore } from 'src/store/main';
import type { Idea, IdeaCategory, IdeaStatus } from 'src/types/api/ideas';
import { IDEA_CATEGORIES, IDEA_STATUSES } from 'src/types/api/ideas';
import IdeasApiService from 'src/services/ideas/IdeasApiService';
import { IDEAS_URL } from 'src/pages/APIs';

const ideasApiService = new IdeasApiService();

export default defineComponent({
  name: 'IdeaBoard',

  setup() {
    const ideasStore = useIdeasStore();
    const userStore = useUserStore();
    const { ideas, loading, pagination } = storeToRefs(ideasStore);

    const currentUserId = Number(userStore.getUserId()) || 0;

    const showNewIdeaDialog = ref(false);
    const showEditIdeaDialog = ref(false);
    const showDeleteDialog = ref(false);
    const submitting = ref(false);
    const submittingEdit = ref(false);
    const currentPage = ref(1);
    const fileInput = ref<HTMLInputElement | null>(null);
    const editFileInput = ref<HTMLInputElement | null>(null);
    const uploadingImage = ref(false);
    const editIdeaId = ref('');
    const deleteIdeaId = ref('');
    const expandedComments = reactive<Record<string, boolean>>({});
    const commentsLoading = reactive<Record<string, boolean>>({});
    const commentText = reactive<Record<string, string>>({});

    const editorToolbar = [
      ['bold', 'italic', 'underline', 'strike'],
      ['unordered', 'ordered'],
      ['link'],
    ];

    const selectedCategory = ref<IdeaCategory | null>(null);
    const selectedStatus = ref<IdeaStatus | null>(null);
    const searchText = ref('');
    const selectedSort = ref('newest');

    const newIdea = ref({
      title: '',
      description: '',
      category: 'feature' as IdeaCategory,
    });

    const editIdea = ref({
      title: '',
      description: '',
      category: 'feature' as IdeaCategory,
    });

    const categoryOptions = IDEA_CATEGORIES;
    const statusOptions = IDEA_STATUSES;

    const sortOptions = [
      { label: 'newest', value: 'newest' },
      { label: 'most_voted', value: 'most_voted' },
    ];

    function categoryColor(category: string): string {
      const colors: Record<string, string> = {
        feature: 'blue',
        improvement: 'teal',
        bug: 'red',
        integration: 'purple',
        other: 'grey',
      };
      return colors[category] || 'grey';
    }

    function statusColor(status: string): string {
      const colors: Record<string, string> = {
        new: 'blue-grey',
        under_review: 'orange',
        planned: 'indigo',
        in_progress: 'cyan',
        done: 'positive',
        declined: 'negative',
      };
      return colors[status] || 'grey';
    }

    function timeAgo(dateStr: string): string {
      const date = new Date(dateStr);
      const now = new Date();
      const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);

      if (seconds < 60) return 'just now';
      const minutes = Math.floor(seconds / 60);
      if (minutes < 60) return `${minutes}m ago`;
      const hours = Math.floor(minutes / 60);
      if (hours < 24) return `${hours}h ago`;
      const days = Math.floor(hours / 24);
      if (days < 30) return `${days}d ago`;
      const months = Math.floor(days / 30);
      return `${months}mo ago`;
    }

    function hasVoted(ideaId: string): boolean {
      return ideasStore.hasVoted(ideaId);
    }

    async function onVote(ideaId: string) {
      await ideasStore.toggleVote(ideaId);
    }

    function onFilterChange() {
      ideasStore.setFilter('category', selectedCategory.value);
      ideasStore.setFilter('status', selectedStatus.value);
      ideasStore.setFilter('search', searchText.value);
      ideasStore.setFilter('sort', selectedSort.value);
      currentPage.value = 1;
      ideasStore.loadIdeas(1);
    }

    function onPageChange(page: number) {
      ideasStore.loadIdeas(page);
    }

    async function onFileSelected(event: Event) {
      const target = event.target as HTMLInputElement;
      const file = target.files?.[0];
      if (!file) return;

      uploadingImage.value = true;
      try {
        const result = await ideasApiService.uploadImage(file);
        if (result.success && result.asset?.url) {
          const imgUrl = IDEAS_URL + result.asset.url;
          newIdea.value.description += `<img src="${imgUrl}" style="max-width:100%;border-radius:8px;margin:8px 0" />`;
        }
      } catch (error) {
        console.error('Failed to upload image:', error);
      } finally {
        uploadingImage.value = false;
        if (fileInput.value) fileInput.value.value = '';
      }
    }

    async function onEditFileSelected(event: Event) {
      const target = event.target as HTMLInputElement;
      const file = target.files?.[0];
      if (!file) return;

      uploadingImage.value = true;
      try {
        const result = await ideasApiService.uploadImage(file);
        if (result.success && result.asset?.url) {
          const imgUrl = IDEAS_URL + result.asset.url;
          editIdea.value.description += `<img src="${imgUrl}" style="max-width:100%;border-radius:8px;margin:8px 0" />`;
        }
      } catch (error) {
        console.error('Failed to upload image:', error);
      } finally {
        uploadingImage.value = false;
        if (editFileInput.value) editFileInput.value.value = '';
      }
    }

    function isCreator(idea: Idea): boolean {
      return idea.created_by === currentUserId;
    }

    function onEditIdea(idea: Idea) {
      editIdeaId.value = idea.id;
      editIdea.value = {
        title: idea.title,
        description: idea.description || '',
        category: idea.category,
      };
      showEditIdeaDialog.value = true;
    }

    async function onSubmitEdit() {
      if (!editIdea.value.title) return;
      submittingEdit.value = true;
      try {
        await ideasStore.updateIdea(editIdeaId.value, {
          title: editIdea.value.title,
          description: editIdea.value.description || undefined,
          category: editIdea.value.category,
        });
        showEditIdeaDialog.value = false;
      } catch (error) {
        console.error('Failed to update idea:', error);
      } finally {
        submittingEdit.value = false;
      }
    }

    function onDeleteIdea(idea: Idea) {
      deleteIdeaId.value = idea.id;
      showDeleteDialog.value = true;
    }

    async function onConfirmDelete() {
      try {
        await ideasStore.deleteIdea(deleteIdeaId.value);
        showDeleteDialog.value = false;
      } catch (error) {
        console.error('Failed to delete idea:', error);
      }
    }

    function getCommentCount(ideaId: string): number {
      const loaded = ideasStore.comments[ideaId];
      if (loaded && loaded.length > 0) return loaded.length;
      const idea = ideas.value.find((i: Idea) => i.id === ideaId);
      return idea?.comment_count ?? 0;
    }

    async function onToggleComments(ideaId: string) {
      if (expandedComments[ideaId]) {
        expandedComments[ideaId] = false;
        return;
      }
      expandedComments[ideaId] = true;
      commentsLoading[ideaId] = true;
      try {
        await ideasStore.loadComments(ideaId);
      } finally {
        commentsLoading[ideaId] = false;
      }
    }

    async function onAddComment(ideaId: string) {
      const text = commentText[ideaId]?.trim();
      if (!text) return;
      try {
        await ideasStore.addComment(ideaId, text);
        commentText[ideaId] = '';
      } catch (error) {
        console.error('Failed to add comment:', error);
      }
    }

    async function onDeleteComment(ideaId: string, commentId: string) {
      try {
        await ideasStore.removeComment(ideaId, commentId);
      } catch (error) {
        console.error('Failed to delete comment:', error);
      }
    }

    async function onSubmitIdea() {
      if (!newIdea.value.title) return;
      submitting.value = true;
      try {
        await ideasStore.createIdea({
          title: newIdea.value.title,
          description: newIdea.value.description || undefined,
          category: newIdea.value.category,
        });
        showNewIdeaDialog.value = false;
        newIdea.value = { title: '', description: '', category: 'feature' };
      } catch (error) {
        console.error('Failed to submit idea:', error);
      } finally {
        submitting.value = false;
      }
    }

    onMounted(() => {
      ideasStore.loadIdeas(1);
    });

    return {
      ideas,
      loading,
      pagination,
      ideasStore,
      currentUserId,
      showNewIdeaDialog,
      showEditIdeaDialog,
      showDeleteDialog,
      submitting,
      submittingEdit,
      currentPage,
      selectedCategory,
      selectedStatus,
      searchText,
      selectedSort,
      newIdea,
      editIdea,
      expandedComments,
      commentsLoading,
      commentText,
      categoryOptions,
      statusOptions,
      sortOptions,
      editorToolbar,
      fileInput,
      editFileInput,
      uploadingImage,
      categoryColor,
      statusColor,
      timeAgo,
      hasVoted,
      isCreator,
      onVote,
      onFilterChange,
      onPageChange,
      onFileSelected,
      onEditFileSelected,
      onSubmitIdea,
      onEditIdea,
      onSubmitEdit,
      onDeleteIdea,
      onConfirmDelete,
      getCommentCount,
      onToggleComments,
      onAddComment,
      onDeleteComment,
    };
  },
});
</script>

